import{_ as n,C as s,o as a,c as l,a2 as c,b as m,w as i,a as o,E as u,a3 as d,j as t}from"./chunks/framework.CAUU6m5Y.js";const k=JSON.parse('{"title":"14.1 Requirements & Capacity Estimation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.1-requirements-and-estimation.md","filePath":"system-design/14.1-requirements-and-estimation.md"}'),h={name:"system-design/14.1-requirements-and-estimation.md"};function p(g,e,f,y,q,R){const r=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=c('<h1 id="_14-1-requirements-capacity-estimation" tabindex="-1">14.1 Requirements &amp; Capacity Estimation <a class="header-anchor" href="#_14-1-requirements-capacity-estimation" aria-label="Permalink to &quot;14.1 Requirements &amp; Capacity Estimation&quot;">​</a></h1><h2 id="_1-functional-non-functional-requirements" tabindex="-1">1. Functional &amp; Non-Functional Requirements <a class="header-anchor" href="#_1-functional-non-functional-requirements" aria-label="Permalink to &quot;1. Functional &amp; Non-Functional Requirements&quot;">​</a></h2><h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><ol><li><strong>Zero Oversell Guarantee</strong>: The system must never sell more units than total allocated stock ($Available + Reserved + Sold == Total$).</li><li><strong>Two-Phase Reservation</strong>: Allow shoppers to hold inventory for 300 seconds while completing payment.</li><li><strong>Automated Rollback</strong>: Release expired reservation holds automatically back to available stock.</li><li><strong>Traffic Regulation</strong>: Enforce a Virtual Waiting Room to queue shoppers and admit them in metered batches.</li><li><strong>Idempotent Payment</strong>: Guarantee that duplicate requests with the same idempotency key never result in duplicate charges.</li></ol><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><ol><li><strong>High Throughput</strong>: Handle 50,000 requests per second at peak sale opening without connection exhaustion.</li><li><strong>Sub-Millisecond Latency</strong>: Reservation availability verification must execute in $&lt; 5\\text{ms}$ at p99.</li><li><strong>Strict Consistency</strong>: Zero data drift or phantom allocations across concurrent threads.</li><li><strong>Availability</strong>: $99.99%$ uptime during peak campaign windows.</li></ol><hr><h2 id="_2-capacity-estimation-back-of-the-envelope-math" tabindex="-1">2. Capacity Estimation &amp; Back-of-the-Envelope Math <a class="header-anchor" href="#_2-capacity-estimation-back-of-the-envelope-math" aria-label="Permalink to &quot;2. Capacity Estimation &amp; Back-of-the-Envelope Math&quot;">​</a></h2><h3 id="traffic-request-rates" tabindex="-1">Traffic &amp; Request Rates <a class="header-anchor" href="#traffic-request-rates" aria-label="Permalink to &quot;Traffic &amp; Request Rates&quot;">​</a></h3><ul><li><strong>Peak Burst Traffic</strong>: 50,000 Requests Per Second (RPS) at sale start.</li><li><strong>Read-to-Write Ratio</strong>: 10:1 (50,000 reads/sec, 5,000 checkout writes/sec).</li><li><strong>Daily Active Shoppers (Flash Drop)</strong>: 500,000 unique users.</li></ul><h3 id="storage-growth" tabindex="-1">Storage Growth <a class="header-anchor" href="#storage-growth" aria-label="Permalink to &quot;Storage Growth&quot;">​</a></h3><ul><li><strong>Order Record Size</strong>: $\\sim 500\\text{ bytes}$</li><li><strong>Reservation Record Size</strong>: $\\sim 250\\text{ bytes}$</li><li><strong>Daily Volume</strong>: 50,000 orders $\\times 500\\text{ bytes} = 25\\text{ MB/day}$ (Negligible storage burden).</li><li><strong>5-Year Growth</strong>: $25\\text{ MB} \\times 365 \\times 5 \\approx 45.6\\text{ GB}$ (Comfortably fits on a single SSD instance).</li></ul><h3 id="memory-sizing-for-in-memory-hot-path" tabindex="-1">Memory Sizing for In-Memory Hot Path <a class="header-anchor" href="#memory-sizing-for-in-memory-hot-path" aria-label="Permalink to &quot;Memory Sizing for In-Memory Hot Path&quot;">​</a></h3><ul><li><strong>Active SKU Stock Counters</strong>: 1,000 active SKUs $\\times 128\\text{ bytes} \\approx 128\\text{ KB}$.</li><li><strong>Waiting Room Queue</strong>: 50,000 concurrent tickets $\\times 128\\text{ bytes} \\approx 6.4\\text{ MB}$.</li><li><strong>Conclusion</strong>: Redis memory footprint is under $100\\text{ MB}$, meaning CPU and network bandwidth are the primary constraints, not RAM.</li></ul><hr><h2 id="_3-capacity-architecture-diagram" tabindex="-1">3. Capacity Architecture Diagram <a class="header-anchor" href="#_3-capacity-architecture-diagram" aria-label="Permalink to &quot;3. Capacity Architecture Diagram&quot;">​</a></h2>',16)),(a(),m(d,null,{default:i(()=>[u(r,{id:"mermaid-134",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Traffic%5B50%2C000%20RPS%20Burst%5D%20--%3E%20LB%5BL7%20Load%20Balancer%3A%2010%20Gbps%20Link%5D%0A%20%20%20%20LB%20--%3E%20WR%5BWaiting%20Room%3A%20Meters%20to%202%2C500%20RPS%5D%0A%20%20%20%20WR%20--%3E%20App%5BFastAPI%20Cluster%3A%2020%20Replicas%20x%20125%20RPS%5D%0A%20%20%20%20App%20--%3E%20Redis%5B(Redis%3A%2050%2C000%20QPS%20in%20RAM)%5D%0A%20%20%20%20App%20--%3E%20DB%5B(PostgreSQL%3A%202%2C500%20Writes%2Fsec)%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t("hr",null,null,-1)),e[3]||(e[3]=t("h2",{id:"_4-30-second-spoken-answer",tabindex:"-1"},[o("4. 30-Second Spoken Answer "),t("a",{class:"header-anchor",href:"#_4-30-second-spoken-answer","aria-label":'Permalink to "4. 30-Second Spoken Answer"'},"​")],-1)),e[4]||(e[4]=t("blockquote",null,[t("p",null,`"For capacity estimation, we model a peak flash drop of 50,000 RPS with a 10-to-1 read-write ratio. By sizing our Virtual Waiting Room to meter downstream entry to 2,500 RPS, we keep write traffic well within PostgreSQL's comfortable write throughput while Redis handles the sub-millisecond stock checks in memory. The storage footprint is compact—under 50 MB per flash sale—making network I/O and lock contention the primary engineering constraints."`)],-1))])}const S=n(h,[["render",p]]);export{k as __pageData,S as default};
